#ifndef CHROME_BROWSER_THEMES_AUTOGENERATED_THEME_SUPPLIER_H_
#define CHROME_BROWSER_THEMES_AUTOGENERATED_THEME_SUPPLIER_H_

#include "base/containers/flat_map.h"
#include "chrome/browser/themes/custom_theme_supplier.h"
#include "chrome/common/themes/autogenerated_theme_util.h"
#include "third_party/skia/include/core/SkColor.h"
#include "ui/gfx/color_utils.h"

// A CustomThemeSupplier that provides autogenerated colors for color themes and
// web apps. Unlike BrowserThemePack, this class does not load or generate
// images, data packs, or PNG assets.
class AutogeneratedThemeSupplier : public CustomThemeSupplier {
 public:
  // Builds an autogenerated theme from `color`.
  static scoped_refptr<AutogeneratedThemeSupplier> CreateForColor(
      SkColor color);

  // Builds an autogenerated theme from `colors`.
  static scoped_refptr<AutogeneratedThemeSupplier> CreateForColors(
      const AutogeneratedThemeColors& colors);

  // Builds an autogenerated theme for Web Apps from `theme_color` and
  // `background_color`.
  static scoped_refptr<AutogeneratedThemeSupplier> CreateForWebAppColors(
      SkColor theme_color,
      SkColor background_color);

  // Public only so that base::MakeRefCounted() can call it. Use the Create*()
  // methods above.
  AutogeneratedThemeSupplier();

  AutogeneratedThemeSupplier(const AutogeneratedThemeSupplier&) = delete;
  AutogeneratedThemeSupplier& operator=(const AutogeneratedThemeSupplier&) =
      delete;

  // CustomThemeSupplier:
  bool GetTint(int id, color_utils::HSL* hsl) const override;
  bool GetColor(int id, SkColor* color) const override;
  bool GetDisplayProperty(int id, int* result) const override;

 protected:
  ~AutogeneratedThemeSupplier() override;

 private:
  // Sets COLOR_FRAME_ACTIVE and related colors.
  void SetFrameColors(SkColor frame_color);

  // CustomThemeSupplier:
  void SetColor(int id, SkColor color) override;

  void SetTint(int id, color_utils::HSL tint);
  void SetDisplayProperty(int id, int value);

  base::flat_map<int, SkColor> colors_;
  base::flat_map<int, color_utils::HSL> tints_;
  base::flat_map<int, int> display_properties_;
};

#endif  // CHROME_BROWSER_THEMES_AUTOGENERATED_THEME_SUPPLIER_H_
